---
import HeroTypographic from "../components/blocks/HeroTypographic.astro";
---

<HeroTypographic
  title="Analytics your whole team can actually read"
  emphasis="actually read"
  lede="Orbit turns product events into one plain-language weekly report, so decisions stop waiting for the data team."
  actions={[
    { label: "Start free", href: "/signup" },
    { label: "Read a sample report", href: "/sample" },
  ]}
  facts={["No SQL required", "SOC 2 Type II", "Setup in an afternoon"]}
/>

---
import AlternatingRows from "../components/blocks/AlternatingRows.astro";
---

<AlternatingRows
  title="How a Fernhill project runs"
  intro="Three phases, each with a clear handover, so you always know what comes next."
  rows={[
    {
      title: "Survey and brief",
      text: "We spend a morning and an evening in the space before drawing anything, recording where the light falls and how you use each room.",
      figure: "2 visits",
      figureLabel: "before the first sketch",
    },
    {
      title: "Design",
      text: "Drawings and a light study for every main room, revised with you until the plan feels obvious.",
      image: { src: "/gallery/atelier.svg", alt: "A sunlit room with an arched window and a long table", width: 1200, height: 1500 },
      link: { label: "See a finished study", href: "/work/light-study" },
    },
    {
      title: "Build",
      text: "We stay on as architects through construction, visiting site weekly and answering the builder's questions the same day.",
      image: { src: "/gallery/field.svg", alt: "A small farmhouse in rolling green fields", width: 1200, height: 900 },
    },
  ]}
/>

